344→func TestNormalizeGeminiTranscript(t *testing.T) {
345→	t.Parallel()
346→
347→	// Raw Gemini format has content as array of objects for user messages,
348→	// plus extra fields (timestamp, model, tokens) that must be preserved.
349→	raw := []byte(`{"sessionId":"abc","messages":[{"id":"m1","type":"user","timestamp":"2026-01-01T10:00:00Z","content":[{"text":"fix the bug"}]},{"id":"m2","type":"gemini","content":"ok","model":"gemini-3-flash","tokens":{"input":100}}]}`)
350→	normalized, err := normalizeGeminiTranscript(raw)
351→	if err != nil {
352→		t.Fatalf("normalizeGeminiTranscript() error: %v", err)
353→	}
354→
355→	// After normalization, content should be a plain string
356→	var result struct {
357→		SessionID string `json:"sessionId"`
358→		Messages  []struct {
359→			ID        string `json:"id"`
360→			Type      string `json:"type"`
361→			Content   string `json:"content"`
362→			Timestamp string `json:"timestamp"`
363→			Model     string `json:"model"`
364→		} `json:"messages"`
365→	}
366→	if err := json.Unmarshal(normalized, &result); err != nil {
367→		t.Fatalf("failed to parse normalized transcript: %v", err)
368→	}
369→	if result.SessionID != "abc" {
370→		t.Errorf("sessionId = %q, want %q", result.SessionID, "abc")
371→	}
372→	if len(result.Messages) != 2 {
373→		t.Fatalf("expected 2 messages, got %d", len(result.Messages))
374→	}
375→	if result.Messages[0].Content != "fix the bug" {
376→		t.Errorf("user content = %q, want %q", result.Messages[0].Content, "fix the bug")
377→	}
378→	if result.Messages[0].Timestamp != "2026-01-01T10:00:00Z" {
379→		t.Errorf("user timestamp = %q, want preserved", result.Messages[0].Timestamp)
380→	}
381→	if result.Messages[1].Content != "ok" {
382→		t.Errorf("gemini content = %q, want %q", result.Messages[1].Content, "ok")
383→	}
384→	if result.Messages[1].Model != "gemini-3-flash" {
385→		t.Errorf("model = %q, want preserved", result.Messages[1].Model)
386→	}
387→}
